import{_ as t,o,c as r,ag as a}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Export to YApi","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export2yapi.md","filePath":"guide/export2yapi.md","lastUpdated":1792912409000}'),i={name:"guide/export2yapi.md"};function s(n,e,l,p,h,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="export-to-yapi" tabindex="-1">Export to YApi <a class="header-anchor" href="#export-to-yapi" aria-label="Permalink to &quot;Export to YApi&quot;">​</a></h1><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="method-1-right-click-export" tabindex="-1">Method 1: Right-Click Export <a class="header-anchor" href="#method-1-right-click-export" aria-label="Permalink to &quot;Method 1: Right-Click Export&quot;">​</a></h3><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Right-click on the file content or folder</li><li>Select <code>ExportYapi</code> to export all APIs in the file or folder</li></ol><h3 id="method-2-shortcut-export" tabindex="-1">Method 2: Shortcut Export <a class="header-anchor" href="#method-2-shortcut-export" aria-label="Permalink to &quot;Method 2: Shortcut Export&quot;">​</a></h3><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Use shortcut <code>Alt + Shift + E</code> (Windows/Linux) or <code>Ctrl + E</code> (macOS)</li><li>Select the APIs to export, choose <code>YApi</code> as the export channel</li><li>Click the ✔ button or press Enter to complete the export</li></ol><h2 id="error-messages" tabindex="-1">Error Messages <a class="header-anchor" href="#error-messages" aria-label="Permalink to &quot;Error Messages&quot;">​</a></h2><p>When the YApi server refuses a request — an invalid or expired token, a missing project, insufficient permissions — the failure notification carries the server&#39;s own rejection text, so the message points at the setting that needs fixing instead of a generic line. Since v3.2.6 a sparse server response (for example a JSON <code>null</code> id on a cart entry) no longer fails the export either: the unusable entry is skipped and the rest is written.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>On first export, the plugin pops up a dialog asking for the <strong>YApi server URL</strong> and the <strong>project token</strong> for the target module. You don&#39;t need to configure them in Settings beforehand — see <a href="/settings/yapi">YApi Settings</a>.</li><li>Once familiar, you can try <a href="/settings/yapi-mock">YApi Mock</a></li></ul>',10)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
